mapper.select:
SELECT o.* FROM course_offerings o
JOIN offering_major_links l ON o.id = l.course_offering_id
WHERE l.major_id = #{majorId}
AND o.academic_year = #{academicYear}
AND o.semester = #{semester}
AND o.course_day = #{courseDay}
AND o.course_time = #{courseTime}

    AND o.id != #{excludeOfferingId}

SELECT o.* FROM course_offerings o
                    JOIN offering_major_links l ON o.id = l.course_offering_id
WHERE l.major_id = #{majorId}
  AND o.academic_year = #{academicYear}
  AND o.semester = #{semester}
  AND l.course_type = 'COMPULSORY'
